import httpStatus from 'http-status';
import { catchAsync } from 'utils/catchAsync';
import { fbRequestService, userService } from 'services';
import ApiError from 'utils/ApiError';

export const fetchAllFriends = catchAsync(async (req, res) => {
  const { limit, page } = req.body;
  const query = { _id: req.user._id };
  const options = { limit, page };
  const friendsList = await fbRequestService.getFriendListWithPagination(
    query,
    options
  );
  res.status(httpStatus.OK).send({
    results: {
      success: true,
      friendsList,
    },
  });
});

export const sendFriendRequest = catchAsync(async (req, res) => {
  await userService.getUserById(req.body.recipient);

  if (req.user.friends.includes(req.body.recipient)) {
    throw new ApiError(httpStatus.NOT_FOUND, 'You are already friend');
  }

  const existingRequestFromRequester =
    await fbRequestService.checkExistingRequest(req.body);

  const existingRequestFromRecipient =
    await fbRequestService.checkExistingRequest({
      requester: req.user._id,
      recipient: req.body.recipient,
    });

  if (existingRequestFromRequester) {
    throw new ApiError(
      httpStatus.NOT_FOUND,
      'You have already sent a friend request to this user.'
    );
  }

  if (existingRequestFromRecipient) {
    throw new ApiError(
      httpStatus.NOT_FOUND,
      'This user has already sent you a friend request.'
    );
  }

  req.body.status = 'pending';
  const request = await fbRequestService.createRequest(req.body);
  res.status(httpStatus.OK).send({
    results: {
      success: true,
      request,
    },
  });
});

